with ranked as (select * from (select *, row_number() over (partition by method, status order by amount desc nulls first, id) as row_num from payments) t where row_num = 1) select date_trunc('quarter', paid_at) as quarter_start, method, round(sum(amount) / nullif(count(case when method = 'cash' then 1 end), 0), 2) as amount_per_cash, size(collect_set(method)) as num_methods from ranked group by quarter_start, method having round(sum(amount) / nullif(count(case when method = 'cash' then 1 end), 0), 2) > 0 order by num_methods nulls last;
